changeSet.sql:
INSERT IGNORE INTO user_group (group_name, description, is_active, tenant_id, created_by, created_at)
SELECT 'SERVICE_AGENT', 'Service Agent / Client Executive group', 1, tenant_id, 'SYSTEM', NOW()
FROM tenant LIMIT 1;

INSERT IGNORE INTO role_list (label, sequence_no, parent_list_id, is_active, tenant_id, created_by, created_at)
SELECT 'SERVICE_AGENT', 99, NULL, 1, tenant_id, 'SYSTEM', NOW()
FROM tenant LIMIT 1;

INSERT IGNORE INTO authority_list (authority_name, description, resource_pattern, tenant_id, created_by, created_at)
SELECT 'SA_VIEW_INVESTORS',         'View assigned investor list',                  '/api/service-agents/me/investors',             t.tenant_id, 'SYSTEM', NOW() FROM tenant t LIMIT 1;
